+      document.addEventListener('visibilitychange', () => {
+        const now = performance.now();
+        if (document.visibilityState === 'visible') {
+          if (visibleSince === null) visibleSince = now;
+        } else if (visibleSince !== null) {
+          accumulated += now - visibleSince;
+          visibleSince = null;
+        }
+      });
