+#!/bin/sh
+# Compiles smallpt.cpp to WebAssembly with Emscripten.
+# Output: smallpt.js (ES module glue) + smallpt.wasm, loaded by worker.js.
+#
+# Notes:
+#  - STACK_SIZE=8MB: radiance() recurses with unbounded depth (Russian
+#    roulette). Emscripten's default 64 KB stack overflows and traps with
+#    "memory access out of bounds"; native builds get 8 MB by default.
+#  - -nostdlib++: the source only needs libc, and linking libc++abi with the
+#    Debian emscripten package fails on __cxa_increment_exception_refcount.
+set -eu
+cd "$(dirname "$0")"
+em++ smallpt.cpp -o smallpt.js \
+  -O3 -flto \
+  -sEXPORT_ES6 \
+  -sENVIRONMENT=web,worker \
+  -sSTRICT \
+  -sALLOW_MEMORY_GROWTH \
+  -sSTACK_SIZE=8MB \
+  -sEXPORTED_FUNCTIONS=_init,_set_colors,_reset_colors,_render_rows,_sphere_count,_malloc,_free \
+  -sEXPORTED_RUNTIME_METHODS=HEAPU8,HEAPF64 \
+  -sFILESYSTEM=0 \
+  -fno-exceptions -fno-rtti -nostdlib++ \
+  -Wno-dangling-else \
+  --no-entry
+ls -la smallpt.js smallpt.wasm
