+  -sALLOW_MEMORY_GROWTH=1 -sFILESYSTEM=0 -sSTACK_SIZE=8MB \
+  -sEXPORTED_FUNCTIONS=_init,_render_rows,_pixels,_set_sphere_color,_sphere_count \
+  -sEXPORTED_RUNTIME_METHODS=HEAPU8
+echo "built smallpt.js ($(wc -c < smallpt.js) bytes)"
