+      document.addEventListener('keydown', function (e) {
+        if (e.key === 'Escape' && activeTrigger) {
+          var t = activeTrigger;
+          close();
+          t.focus();
+        }
+      });
+
+      window.addEventListener('scroll', function () {
+        if (activeTrigger) position(activeTrigger);
+      }, { passive: true });
+      window.addEventListener('resize', function () {
+        if (activeTrigger) position(activeTrigger);
+      });
+    })();
