+    // ---------------------------------------------------------------------
+    // Session registry (used by Ask the Barista + Conversation Branching)
+    // ---------------------------------------------------------------------
+
+    const MAX_SESSIONS = 4;               // hard cap on simultaneously alive sessions
+    const QUOTA_RECYCLE_THRESHOLD = 0.9;  // recycle a session when 90% of its context is used
