+
+    const askBtn = $('ask-the-barista');
+    const stopBtn = $('barista-stop');
+    const questionEl = $('barista-question');
+    const answerEl = $('barista-answer');
+    const baristaStatus = $('barista-status');
+    const baristaProgress = $('barista-progress');
+
+    /** AbortController for the in-flight barista request (create + stream). */
+    let baristaController = null;
+
+    /**
+     * Return the active barista session, creating a root session if needed and
+     * recycling it if the context window is almost full.
+     */
+    async function ensureBaristaSession(signal) {
+      let entry = getActiveEntry();
+
+      if (entry) {
+        const { fraction } = usageOf(entry.session);
+        if (fraction >= QUOTA_RECYCLE_THRESHOLD) {
