+                  autoComplete="new-password"
+                  disabled={loading}
+                  className={inputClass}
+                />
+                <p className="text-xs text-gray-500 mt-1">Must be at least 8 characters and contain a number.</p>
+              </div>
+
+              <button type="submit" disabled={loading} data-skip-tracking="true" className={primaryButtonClass}>
+                {loading ? 'Signing up...' : 'Sign Up'}
+              </button>
+            </form>
+          )}
+        </>
+      )}
+
+      {step !== 'offer-passkey' && (
+        <p className="mt-6 text-sm text-center text-gray-600">
+          Already have an account?{' '}
+          <a href={`${baseUrl}signin`} data-skip-tracking="true" className="font-medium text-gray-900 underline hover:text-amber-500">
+            Sign in
+          </a>
+        </p>
+      )}
     </div>
   );
 }
