+/** Where to send users after signing in. Only same-site paths under the app base are honoured. */
+export function resolveNextUrl(search: string = typeof window !== 'undefined' ? window.location.search : ''): string {
+  const base = import.meta.env.BASE_URL;
+  const fallback = `${base}account`;
+  const next = new URLSearchParams(search).get('next');
+  if (!next) return fallback;
+  if (!next.startsWith(base) || next.startsWith('//') || /[\\\n\r]/.test(next)) return fallback;
+  return next;
+}
+
+export function formatRelativeTime(iso: string | number | null | undefined, now = Date.now()): string {
+  if (!iso) return 'never';
+  const then = typeof iso === 'number' ? iso : Date.parse(iso);
+  if (Number.isNaN(then)) return 'unknown';
+  const diff = now - then;
+  const minutes = Math.round(diff / 60_000);
+  if (minutes < 1) return 'just now';
+  if (minutes < 60) return `${minutes} minute${minutes === 1 ? '' : 's'} ago`;
+  const hours = Math.round(minutes / 60);
+  if (hours < 24) return `${hours} hour${hours === 1 ? '' : 's'} ago`;
+  const days = Math.round(hours / 24);
+  if (days < 30) return `${days} day${days === 1 ? '' : 's'} ago`;
+  return new Date(then).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
+}
+
+export function formatDate(iso: string | null | undefined): string {
+  if (!iso) return '—';
+  const d = new Date(iso);
+  if (Number.isNaN(d.valueOf())) return '—';
+  return d.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
+}
