index 0000000..4baa48b
--- /dev/null
+++ b/src/pages/api/auth/passkeys/index.ts
@@ -0,0 +1,20 @@
+import type { APIRoute } from 'astro';
+import { getRelyingParty } from '../../../../lib/auth/rp';
+import { apiError, getSessionUser, json } from '../../../../lib/auth/session';
+import { listCredentials } from '../../../../lib/auth/store';
+import { serializeCredential } from '../../../../lib/auth/describe';
+
+export const prerender = false;
+
+/** List the signed-in user's passkeys. */
+export const GET: APIRoute = async ({ request, session }) => {
