+ *   needs them. `browsing-topics=()` also opts the site out of the Topics API.
+ * - X-Content-Type-Options: stop browsers sniffing responses into scripts.
+ */
+const PRIVACY_HEADERS: Record<string, string> = {
+  'Referrer-Policy': 'strict-origin-when-cross-origin',
+  'Permissions-Policy': [
+    'accelerometer=()',
+    'browsing-topics=()',
+    'camera=()',
+    'geolocation=()',
+    'gyroscope=()',
+    'magnetometer=()',
+    'microphone=()',
+    'payment=()',
+    'usb=()',
+  ].join(', '),
+  'X-Content-Type-Options': 'nosniff',
+};
+
+function withPrivacyHeaders(response: Response): Response {
+  try {
+    for (const [name, value] of Object.entries(PRIVACY_HEADERS)) {
+      response.headers.set(name, value);
+    }
+    return response;
+  } catch {
+    // Some responses (e.g. Response.redirect) have immutable headers; copy them.
+    const copy = new Response(response.body, response);
+    for (const [name, value] of Object.entries(PRIVACY_HEADERS)) {
+      copy.headers.set(name, value);
+    }
+    return copy;
+  }
