+  <script type="module">
+    // Load the <input type="checkbox" switch> polyfill only where the browser
+    // lacks native support (currently everything except Safari 17.4+).
+    if (!('switch' in HTMLInputElement.prototype)) {
+      import('https://unpkg.com/input-switch-polyfill@1.12.0/input-switch-polyfill.js');
+    }
+
+    // Persist the preference. A switch is still a checkbox: read `.checked` on `change`.
+    const STORAGE_KEY = 'daily-grind:seasonal-alerts';
+    const seasonalAlerts = document.getElementById('seasonal-alerts');
+
+    try {
+      seasonalAlerts.checked = localStorage.getItem(STORAGE_KEY) === 'true';
+    } catch {
+      // Storage unavailable (private mode, blocked cookies): fall back to unchecked.
+    }
+
+    seasonalAlerts.addEventListener('change', () => {
+      try {
+        localStorage.setItem(STORAGE_KEY, String(seasonalAlerts.checked));
+      } catch {
