+
+        if (lang === SOURCE_LANG) {
+          restoreOriginal();
+          setStatus('');
+          return Promise.resolve();
+        }
+
+        if (cache[lang]) {
+          applyTexts(cache[lang], lang);
+          setStatus('');
+          return Promise.resolve();
+        }
+
+        if (!supportsTranslator()) {
+          restoreOriginal();
+          if (!opts.quiet) {
+            flashStatus('On-device translation is not available in this browser yet. Try a recent version of Chrome.', 'error', 6000);
+          }
+          return Promise.resolve();
+        }
+
+        select.disabled = true;
+        setStatus('Preparing ' + languageName(lang) + ' translation on your device…');
+
+        var options = { sourceLanguage: SOURCE_LANG, targetLanguage: lang };
+
+        return Promise.resolve()
+          .then(function () {
+            return self.Translator.availability(options);
+          })
+          .then(function (availability) {
+            if (availability === 'unavailable') {
+              throw new Error(languageName(lang) + ' is not supported for on-device translation.');
+            }
+            if (availability !== 'available') {
+              setStatus('Downloading ' + languageName(lang) + ' language pack to your device…');
+            }
+            options.monitor = function (m) {
+              m.addEventListener('downloadprogress', function (e) {
+                if (myRequest !== requestId) return;
+                var fraction = e.total ? e.loaded / e.total : e.loaded;
+                var pct = Math.min(100, Math.round(fraction * 100));
+                setStatus('Downloading ' + languageName(lang) + ' language pack… ' + pct + '%');
+              });
+            };
+            return self.Translator.create(options);
+          })
+          .then(function (translator) {
+            return translateAll(translator).then(function (texts) {
+              if (typeof translator.destroy === 'function') translator.destroy();
+              return texts;
+            }, function (err) {
+              if (typeof translator.destroy === 'function') translator.destroy();
+              throw err;
+            });
+          })
+          .then(function (texts) {
+            cache[lang] = texts;
+            if (myRequest !== requestId) return;
+            applyTexts(texts, lang);
+            flashStatus('Translated to ' + languageName(lang) + ' on your device.');
+          })
+          .catch(function (err) {
+            if (myRequest !== requestId) return;
+            restoreOriginal();
+            var message;
+            if (err && err.name === 'NotAllowedError') {
+              message = 'Choose a language again to start the download.';
+            } else {
+              message = (err && err.message) || 'Translation failed. Please try again.';
+            }
+            if (!opts.quiet) flashStatus(message, 'error', 6000);
+          })
+          .then(function () {
+            if (myRequest === requestId) select.disabled = false;
+          });
+      }
+
+      select.addEventListener('change', function () {
+        var lang = select.value;
+        try { localStorage.setItem(STORAGE_KEY, lang); } catch (e) { /* storage unavailable */ }
+        applyLanguage(lang);
+      });
+
+      // Restore a previously chosen language. If the language pack is not
+      // downloaded yet the browser may require a user gesture, in which case
+      // we quietly stay in English and leave the selector ready to use.
+      var saved = null;
+      try { saved = localStorage.getItem(STORAGE_KEY); } catch (e) { /* storage unavailable */ }
+      if (saved && saved !== SOURCE_LANG && select.querySelector('option[value="' + saved + '"]')) {
+        select.value = saved;
+        applyLanguage(saved, { quiet: true });
+      }
+    })();
+  </script>
+
 </body>

