+++ b/src/utils/semantics.ts
@@ -0,0 +1,418 @@
+/**
+ * Semantic context for editorial content.
+ *
+ * Components in `src/components/semantic/` do not receive visual props such as
+ * "red" or "large". They receive an article, derive a semantic context from it
+ * with `getSemanticContext`, and pick their visual treatment from the token
+ * maps below. Change the mapping here and every surface follows.
+ *
+ * Four axes are derived:
+ *
+ *   desk       what newsroom desk the story belongs to (from `category`)
+ *   freshness  how old the story is relative to the edition (from `date`)
+ *   depth      how much of the reader's time it asks for (from `readingTime`)
+ *   tone       what kind of piece it is (from `tags` and the headline)
+ */
+
+export type Desk =
+  | 'news'
+  | 'business'
+  | 'culture'
+  | 'science'
+  | 'sports'
+  | 'lifestyle';
+
+export type Freshness = 'breaking' | 'new' | 'recent' | 'archive';
+export type Depth = 'brief' | 'standard' | 'longform';
+export type Tone = 'report' | 'analysis' | 'feature' | 'opinion';
+
+/** The subset of article frontmatter the semantic model reads. */
+export interface SemanticSource {
+  title: string;
+  category: string;
+  date: Date;
+  readingTime?: number;
+  tags?: string[];
+}
+
+export interface SemanticContext {
+  desk: Desk;
+  freshness: Freshness;
+  depth: Depth;
+  tone: Tone;
+  /** Minutes between the story's date and the reference time. */
+  ageMinutes: number;
+  /** Reading time in minutes, defaulting to 3 when unknown. */
+  minutes: number;
+}
+
+export interface SemanticOptions {
+  /**
+   * Reference point for freshness. Defaults to the current time. Sections pass
+   * the date of their newest story so freshness means "new in this edition",
+   * which keeps the states meaningful for a static content corpus.
+   */
+  now?: Date | number;
+}
+
+// ---------------------------------------------------------------------------
+// Derivation
+// ---------------------------------------------------------------------------
+
+const DESK_BY_CATEGORY: Record<string, Desk> = {
+  news: 'news',
+  national: 'news',
+  politics: 'news',
+  labor: 'news',
+  world: 'news',
+  economy: 'business',
+  business: 'business',
+  markets: 'business',
+  culture: 'culture',
+  media: 'culture',
+  arts: 'culture',
+  science: 'science',
+  technology: 'science',
+  tech: 'science',
+  health: 'science',
+  sports: 'sports',
+  lifestyle: 'lifestyle',
+  pets: 'lifestyle',
+  travel: 'lifestyle',
+  food: 'lifestyle',
+  'urban development': 'lifestyle',
+  'web development': 'science',
+};
+
+export function getDesk(category: string): Desk {
+  return DESK_BY_CATEGORY[category.trim().toLowerCase()] ?? 'news';
+}
+
+const MINUTE = 60_000;
+const HOUR = 60 * MINUTE;
+const DAY = 24 * HOUR;
+
+export const FRESHNESS_WINDOWS = {
+  breaking: 6 * HOUR,
+  new: 2 * DAY,
+  recent: 14 * DAY,
+} as const;
+
+export function getFreshness(date: Date, now: Date | number = Date.now()): Freshness {
+  const age = toMillis(now) - date.valueOf();
+  if (age <= FRESHNESS_WINDOWS.breaking) return 'breaking';
+  if (age <= FRESHNESS_WINDOWS.new) return 'new';
+  if (age <= FRESHNESS_WINDOWS.recent) return 'recent';
+  return 'archive';
+}
+
+export function getDepth(readingTime?: number): Depth {
+  const minutes = readingTime ?? 3;
+  if (minutes <= 3) return 'brief';
+  if (minutes <= 6) return 'standard';
+  return 'longform';
+}
+
+const OPINION_TAGS = new Set(['opinion', 'editorial', 'column', 'letter']);
+const ANALYSIS_TAGS = new Set(['analysis', 'explainer', 'policy', 'economy']);
+const FEATURE_TAGS = new Set(['humor', 'profile', 'feature', 'interview', 'photo essay']);
+
+export function getTone(source: Pick<SemanticSource, 'title' | 'tags' | 'readingTime'>): Tone {
+  const tags = (source.tags ?? []).map((t) => t.toLowerCase());
+  if (tags.some((t) => OPINION_TAGS.has(t))) return 'opinion';
+  if (tags.some((t) => FEATURE_TAGS.has(t))) return 'feature';
+  // A headline that asks a question is the newsroom convention for analysis.
+  if (tags.some((t) => ANALYSIS_TAGS.has(t)) || /\?\s*$/.test(source.title)) return 'analysis';
+  if ((source.readingTime ?? 0) >= 5) return 'feature';
+  return 'report';
+}
+
+export function getSemanticContext(
+  source: SemanticSource,
+  options: SemanticOptions = {},
+): SemanticContext {
+  const now = options.now ?? Date.now();
+  return {
+    desk: getDesk(source.category),
+    freshness: getFreshness(source.date, now),
+    depth: getDepth(source.readingTime),
+    tone: getTone(source),
+    ageMinutes: Math.max(0, Math.round((toMillis(now) - source.date.valueOf()) / MINUTE)),
+    minutes: source.readingTime ?? 3,
+  };
+}
+
+// ---------------------------------------------------------------------------
+// Visual tokens
+//
+// Every class string below is written out in full so Tailwind can find it when
+// it scans the source tree. Never build class names by concatenation.
+// ---------------------------------------------------------------------------
+
+export interface DeskTheme {
+  label: string;
+  /** Text colour for kickers, tags and metadata. */
+  text: string;
+  /** Headline hover colour. */
+  hover: string;
+  /** Hairline and rule colour. */
+  border: string;
+  /** Soft tinted background for chips and section bands. */
+  tint: string;
+  /** Solid fill, used for progress bars and dots. */
+  fill: string;
+  /** Gradient overlay used on category hero headers. */
+  overlay: string;
+}
+
+export const DESK_THEME: Record<Desk, DeskTheme> = {
+  news: {
+    label: 'News',
+    text: 'text-red-800',
+    hover: 'group-hover:text-red-700',
+    border: 'border-red-800',
+    tint: 'bg-red-50',
+    fill: 'bg-red-700',
+    overlay: 'from-red-950/80 to-red-900/40',
+  },
+  business: {
+    label: 'Business',
+    text: 'text-emerald-800',
+    hover: 'group-hover:text-emerald-700',
+    border: 'border-emerald-800',
+    tint: 'bg-emerald-50',
+    fill: 'bg-emerald-700',
+    overlay: 'from-emerald-950/80 to-emerald-900/40',
+  },
+  culture: {
+    label: 'Culture',
+    text: 'text-fuchsia-800',
+    hover: 'group-hover:text-fuchsia-700',
+    border: 'border-fuchsia-800',
+    tint: 'bg-fuchsia-50',
+    fill: 'bg-fuchsia-700',
+    overlay: 'from-fuchsia-950/80 to-fuchsia-900/40',
+  },
+  science: {
+    label: 'Science',
+    text: 'text-sky-800',
+    hover: 'group-hover:text-sky-700',
+    border: 'border-sky-800',
+    tint: 'bg-sky-50',
+    fill: 'bg-sky-700',
+    overlay: 'from-sky-950/80 to-sky-900/40',
+  },
+  sports: {
+    label: 'Sports',
+    text: 'text-orange-800',
+    hover: 'group-hover:text-orange-700',
+    border: 'border-orange-800',
+    tint: 'bg-orange-50',
+    fill: 'bg-orange-600',
+    overlay: 'from-orange-950/80 to-orange-900/40',
+  },
+  lifestyle: {
+    label: 'Lifestyle',
+    text: 'text-teal-800',
+    hover: 'group-hover:text-teal-700',
+    border: 'border-teal-800',
+    tint: 'bg-teal-50',
+    fill: 'bg-teal-700',
+    overlay: 'from-teal-950/80 to-teal-900/40',
+  },
+};
+
+export interface FreshnessTheme {
+  label: string;
+  /** Pill styling for the badge. Empty when the state has no badge. */
+  badge: string;
+  /** Dot shown inside the badge. Empty when the state has no dot. */
+  dot: string;
+  /** Treatment applied to the story image. */
+  image: string;
+  /** Treatment applied to the headline. */
+  headline: string;
+  /** Edge accent applied to the card container. */
+  card: string;
+}
+
+export const FRESHNESS_THEME: Record<Freshness, FreshnessTheme> = {
+  breaking: {
+    label: 'Breaking',
+    badge: 'bg-red-700 text-white',
+    dot: 'bg-white animate-pulse',
+    image: '',
+    headline: 'font-bold',
+    card: 'border-l-4 border-red-700 pl-4',
+  },
+  new: {
+    label: 'New',
+    badge: 'bg-amber-100 text-amber-900 ring-1 ring-amber-300',
+    dot: 'bg-amber-500',
+    image: '',
+    headline: '',
+    card: '',
+  },
+  recent: {
+    label: '',
+    badge: '',
+    dot: '',
+    image: '',
+    headline: '',
+    card: '',
+  },
+  archive: {
+    label: 'From the archive',
+    badge: 'bg-gray-100 text-gray-600 ring-1 ring-gray-200',
+    dot: '',
+    image: 'sepia-[.25] contrast-[.95]',
+    headline: 'text-gray-700',
+    card: '',
+  },
+};
+
+export interface DepthTheme {
+  label: string;
+  /** Number of filled pips out of three. */
+  pips: 1 | 2 | 3;
+  /** Whether a grid card should spend space on the summary. */
+  showSummary: boolean;
+  /** Headline scale on the grid surface. */
+  headline: string;
+}
+
+export const DEPTH_THEME: Record<Depth, DepthTheme> = {
+  brief: { label: 'Quick read', pips: 1, showSummary: false, headline: 'text-lg' },
+  standard: { label: '', pips: 2, showSummary: true, headline: 'text-lg md:text-xl' },
+  longform: { label: 'Long read', pips: 3, showSummary: true, headline: 'text-xl md:text-2xl' },
+};
+
+export interface ToneTheme {
+  /** Kicker text shown next to the desk tag. Empty for straight reports. */
+  kicker: string;
+  kickerClass: string;
+  /** Headline typography. */
+  headline: string;
+  /** Image aspect ratio on the grid surface. */
+  aspect: string;
+  /** Whether the byline is promoted on cards. */
+  showByline: boolean;
+}
+
+export const TONE_THEME: Record<Tone, ToneTheme> = {
+  report: {
+    kicker: '',
+    kickerClass: '',
+    headline: 'font-brand',
+    aspect: 'aspect-[16/9]',
+    showByline: false,
+  },
+  analysis: {
+    kicker: 'Analysis',
+    kickerClass: 'text-gray-500 italic',
+    headline: 'font-brand',
+    aspect: 'aspect-[16/9]',
+    showByline: false,
+  },
+  feature: {
+    kicker: 'Feature',
+    kickerClass: 'text-gray-500',
+    headline: 'font-brand',
+    aspect: 'aspect-[4/3]',
+    showByline: true,
+  },
+  opinion: {
+    kicker: 'Opinion',
+    kickerClass: 'text-gray-900 font-semibold',
+    headline: 'font-brand italic',
+    aspect: 'aspect-square',
+    showByline: true,
+  },
+};
+
+// ---------------------------------------------------------------------------
+// Dateline
+// ---------------------------------------------------------------------------
+
+/**
+ * Formats a story date in the register its freshness calls for:
+ * minutes or hours ago while it is breaking or new, the weekday while it is
+ * recent, and a full date once it is archive material.
+ */
+export function formatDateline(date: Date, now: Date | number = Date.now()): string {
+  const freshness = getFreshness(date, now);
+  const age = toMillis(now) - date.valueOf();
+
+  if (freshness === 'breaking') {
+    const minutes = Math.max(1, Math.round(age / MINUTE));
+    if (minutes < 60) return `${minutes} min ago`;
+    const hours = Math.round(age / HOUR);
+    return hours === 1 ? '1 hour ago' : `${hours} hours ago`;
+  }
+  if (freshness === 'new') {
+    const hours = Math.round(age / HOUR);
+    if (hours < 24) return hours <= 1 ? '1 hour ago' : `${hours} hours ago`;
+    return 'Yesterday';
+  }
+  if (freshness === 'recent') {
+    return date.toLocaleDateString('en-US', { weekday: 'long' });
+  }
+  return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
+}
+
+// ---------------------------------------------------------------------------
+// Aggregates
+// ---------------------------------------------------------------------------
+
+export interface CollectionSemantics {
+  /** The single desk shared by every story, or null when desks are mixed. */
+  sharedDesk: Desk | null;
+  /** True when at least one story is breaking. */
+  hasBreaking: boolean;
+  /** Index of the story that should lead the section. */
+  leadIndex: number;
+  /** The newest story date, used as the edition reference. */
+  editionDate: Date;
+}
+
+/**
+ * Looks across a set of stories to decide how a section should present them.
+ * A breaking story leads regardless of order. When every story comes from the
+ * same desk the section can take on that desk's identity and the cards can
+ * stop repeating it.
+ */
+export function getCollectionSemantics(
+  sources: SemanticSource[],
+  options: SemanticOptions = {},
+): CollectionSemantics {
+  if (sources.length === 0) {
+    return { sharedDesk: null, hasBreaking: false, leadIndex: 0, editionDate: new Date(0) };
+  }
+  const editionDate = new Date(Math.max(...sources.map((s) => s.date.valueOf())));
+  const now = options.now ?? editionDate;
+  const contexts = sources.map((s) => getSemanticContext(s, { now }));
+
+  const desks = new Set(contexts.map((c) => c.desk));
+  const breakingIndex = contexts.findIndex((c) => c.freshness === 'breaking');
+
+  return {
+    sharedDesk: desks.size === 1 ? contexts[0].desk : null,
+    hasBreaking: breakingIndex !== -1,
+    leadIndex: breakingIndex === -1 ? 0 : breakingIndex,
+    editionDate,
+  };
+}
+
+/** Builds the `data-*` attribute bag used for styling hooks and debugging. */
+export function semanticDataAttributes(ctx: SemanticContext) {
+  return {
+    'data-desk': ctx.desk,
+    'data-freshness': ctx.freshness,
+    'data-depth': ctx.depth,
+    'data-tone': ctx.tone,
+  };
+}
+
+function toMillis(value: Date | number): number {
+  return typeof value === 'number' ? value : value.valueOf();
+}

